const drive = $('Google Drive Trigger').first().json || {};
const downloaded = $('Download File').first();

const binary = Object.values(downloaded.binary || {})[0] || {};

const name = String(
  binary.fileName || drive.name || ''
).trim();

const lower = name.toLowerCase();

const mime = String(
  binary.mimeType || drive.mimeType || ''
).toLowerCase();

const extension = String(
  binary.fileExtension || ''
).toLowerCase();

const props = drive.appProperties || {};
// --------------------------------------------------
// 1. Validate the source file
// --------------------------------------------------

// --------------------------------------------------
// 1. Validate the source file
// --------------------------------------------------

const isCsv =
  lower.endsWith('.csv') ||
  extension === 'csv' ||
  mime === 'text/csv' ||
  mime === 'application/csv';

const isPdf =
  lower.endsWith('.pdf') ||
  extension === 'pdf' ||
  mime === 'application/pdf';

if (isPdf && !isCsv) {
  throw new Error(
    'Manual review required: PDF statements are not supported'
  );
}

if (!isCsv) {
  throw new Error(
    'Manual review required: only CSV statements are supported. ' +
    'Detected filename: ' + name +
    ', MIME type: ' + mime
  );
}
// --------------------------------------------------
// 2. Detect the streaming platform
// --------------------------------------------------

const known = [
  [/spotify/i, 'Spotify'],
  [/apple/i, 'Apple Music'],
  [/youtube/i, 'YouTube Music'],
  [/amazon/i, 'Amazon Music'],
  [/audiomack/i, 'Audiomack'],
];

const found = known.find(([pattern]) => pattern.test(name));

// Supports filenames like:
// Spotify_Royalty_Statement_2026-Q1.csv
const filenameMatch = name.match(
  /^(.+?)_Royalty_Statement_(20\d{2}-Q[1-4])(?:[-_][^.]+)?\.csv$/i
);

const platform = String(
  props.platform ||
  $env.ROYALTYGUARD_PLATFORM ||
  (filenameMatch
    ? filenameMatch[1].replace(/_/g, ' ')
    : found?.[1] || '')
).trim();

// --------------------------------------------------
// 3. Detect the statement period
// --------------------------------------------------


const periodMatch = name.match(
  /20\d{2}(?:-Q[1-4]|-(?:0[1-9]|1[0-2])(?:-\d{2})?)/i
);


const statementPeriod = String(
  props.statementPeriod ||
  $env.ROYALTYGUARD_STATEMENT_PERIOD ||
  (periodMatch ? periodMatch[0] : '')
).trim().toUpperCase();

// Stop if metadata is missing
if (!platform || !statementPeriod) {
  throw new Error(
    'Manual review required: platform and statementPeriod are required. ' +
    'File name: "' + (name || '(missing)') + '". ' +
    'Detected platform: "' + (platform || '(missing)') + '". ' +
    'Detected period: "' + (statementPeriod || '(missing)') + '".'
  );
}

// --------------------------------------------------
// 4. Get the extracted CSV rows and AI normalization
// --------------------------------------------------

const source = $('Extract From File').all();
const out = $input.first().json.output;

if (
  !source.length ||
  !out ||
  !Array.isArray(out.rows) ||
  out.rows.length !== source.length
) {
  throw new Error(
    'AI normalization output does not match the CSV row count'
  );
}

// --------------------------------------------------
// 5. Validate required source fields
// --------------------------------------------------

const pick = (row, keys, label) => {
  for (const k of keys) {
    const v = row[k];

    if (
      v !== undefined &&
      v !== null &&
      String(v).trim() !== ''
    ) {
      return String(v).trim();
    }
  }

  throw new Error('CSV row is missing ' + label);
};

// --------------------------------------------------
// 6. Validate every CSV row against the AI output
// --------------------------------------------------

const rows = source.map((item, i) => {
  const src = item.json || {};
  const n = i + 1;

  const trackName = pick(
    src,
    ['trackName', 'track_name', 'track', 'title'],
    'trackName'
  );

  const eligibleUnits = pick(
    src,
    ['eligibleUnits', 'eligible_units', 'plays', 'streams', 'units'],
    'eligibleUnits'
  );

  const territory = pick(
    src,
    ['territory', 'country', 'countryCode'],
    'territory'
  ).toUpperCase();

  const actualPayout = pick(
    src,
    ['actualPayout', 'actual_payout', 'payout', 'royalty'],
    'actualPayout'
  );

  const tier = src.tier ?? src.rateTier ?? null;

  // Validate numeric values
  if (!/^\d+$/.test(eligibleUnits)) {
    throw new Error(
      'Invalid eligibleUnits value in CSV row ' + n
    );
  }

  if (
    !/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(actualPayout)
  ) {
    throw new Error(
      'Invalid actualPayout value in CSV row ' + n
    );
  }

  // Tier-specific rates require manual review
  if (tier !== null && String(tier).trim() !== '') {
    throw new Error(
      'Manual review required: tier-specific rates are not supported (row ' +
      n + ')'
    );
  }

  // Compare AI-normalized data against original CSV data
  const r = out.rows[i] || {};

  if (
    String(r.trackName || '').trim() !== trackName ||
    !Number.isSafeInteger(r.plays) ||
    BigInt(r.plays) !== BigInt(eligibleUnits) ||
    String(r.territory || '').trim().toUpperCase() !== territory ||
    String(r.actualPayout ?? '') !== actualPayout
  ) {
    throw new Error(
      'AI output differs from CSV source for row ' + n
    );
  }

  return {
    trackName,
    eligibleUnits,
    territory,
    tier: null,
    actualPayout,
  };
});

// --------------------------------------------------
// 7. Return normalized royalty data and source metadata
// --------------------------------------------------

return [
  {
    json: {
      platform,
      statementPeriod,
      rows,
      sourceMetadata: {
        sourceFileId: String(drive.id || ''),
        fileName: name,
        mimeType: mime || 'text/csv',
        sourceLocation: String(
          drive.webViewLink ||
          (
            drive.id
              ? 'https://drive.google.com/open?id=' + drive.id
              : ''
          )
        ),
        createdTime: drive.createdTime || undefined,
        modifiedTime: drive.modifiedTime || undefined,
      },
    },
  },
];

const ack = $input.first().json;
const statementId = Number(ack.data && ack.data.statementId);
if (!Number.isSafeInteger(statementId) || statementId < 1) throw new Error('Backend did not return a valid statementId');
const s = $('Normalize Royalty Data').first().json;
return s.rows.map(row => ({ json: Object.assign({ statementId, platform: s.platform, statementPeriod: s.statementPeriod, sourceMetadata: s.sourceMetadata }, row) }));

const responses = $input.all();
const rows = $('Expand Rate Requests').all();
if (!rows.length || rows.length !== responses.length) throw new Error('Rate response count does not match royalty rows');
const parse = (v, s, f) => {
  const m = /^(0|[1-9]\d*)(?:\.(\d+))?$/.exec(String(v));
  if (!m) throw new Error(f + ' must be a non-negative decimal');
  const d = m[2] || '';
  if (d.length > s && /[^0]/.test(d.slice(s))) throw new Error(f + ' exceeds supported precision');
  return BigInt(m[1]) * 10n ** BigInt(s) + BigInt(d.slice(0, s).padEnd(s, '0') || '0');
};
const fmt = (v, s) => {
  const neg = v < 0n;
  const n = neg ? -v : v;
  return (neg ? '-' : '') + (n / 10n ** BigInt(s)).toString() + '.' + (n % 10n ** BigInt(s)).toString().padStart(s, '0');
};
const threshold = parse($env.ROYALTYGUARD_DISCREPANCY_THRESHOLD || '0.00', 2, 'threshold');
let expected = 0n, actual = 0n, difference = 0n, discrepancyCount = 0;
const results = rows.map((item, i) => {
  const row = item.json;
  const body = responses[i].json;
  const rate = body.data && body.data.rate !== undefined ? body.data.rate : body.rate;
  if (rate === undefined) throw new Error('Rate API response must contain rate');
  const actualCents = parse(row.actualPayout, 2, 'actualPayout');
  const expectedCents = (BigInt(row.eligibleUnits) * parse(rate, 6, 'rate') + 5000n) / 10000n;
  const diff = expectedCents - actualCents;
  const isDiscrepancy = diff > threshold;
  expected += expectedCents; actual += actualCents; difference += diff;
  if (isDiscrepancy) discrepancyCount++;
  return { trackName: row.trackName, eligibleUnits: row.eligibleUnits, territory: row.territory, tier: null, actualPayout: fmt(actualCents, 2), rate: String(rate), expectedPayout: fmt(expectedCents, 2), difference: fmt(diff, 2), shortfall: diff > 0n ? fmt(diff, 2) : '0.00', isDiscrepancy };
});
const first = rows[0].json;
return [{ json: { statementId: first.statementId, sourceFileId: first.sourceMetadata.sourceFileId, threshold: fmt(threshold, 2), totalExpected: fmt(expected, 2), totalActual: fmt(actual, 2), totalDifference: fmt(difference, 2), discrepancyCount, results, potentialDiscrepancy: discrepancyCount > 0, resultLabel: 'potential_discrepancy_for_review' } }];

const hookRan = $('Webhook - Approved Dispute Send').isExecuted;
if (hookRan) {
  const hook = $('Webhook - Approved Dispute Send').first().json.body;
  const sent = $('Gmail - Dispute').first().json;
  const esc = $input.first().json;
  return [{ json: { stage: 'dispute_follow_up_complete', disputeId: hook.dispute.id, recipient: hook.dispute.recipient, subject: hook.dispute.subject, disputeMessageId: sent.id || null, threadId: sent.threadId || null, escalationMessageId: esc.id || null, escalationSentTo: $env.ROYALTYGUARD_ESCALATION_APPROVER_EMAIL || null, replyChecked: false, completedAt: new Date().toISOString() } }];
}
const calc = $('Calculate Royalty Leakage').first().json;
const meta = $('Normalize Royalty Data').first().json;
return [{ json: { stage: 'audit_complete', fileName: meta.sourceMetadata.fileName, platform: meta.platform, statementPeriod: meta.statementPeriod, statementId: calc.statementId, totalExpected: calc.totalExpected, totalActual: calc.totalActual, totalDifference: calc.totalDifference, discrepancyCount: calc.discrepancyCount, potentialDiscrepancy: calc.potentialDiscrepancy, next: calc.potentialDiscrepancy ? 'Open the persisted discrepancy in RoyaltyGuard, generate the backend draft, review it, then send.' : 'No discrepancy above the threshold. No dispute needed.', completedAt: new Date().toISOString() } }];
